args.script:
using UnityEngine;
using UnityEngine.Rendering.Universal;

// === 1. Configure Main Camera: Orthographic, tilted 30 degrees from top-down ===
var camObj = Camera.main != null ? Camera.main.gameObject : GameObject.Find("Main Camera");
if (camObj == null)
{
    camObj = new GameObject("Main Camera");
    camObj.AddComponent<Camera>();
    camObj.AddComponent<AudioListener>();
    camObj.tag = "MainCamera";
}

var cam = camObj.GetComponent<Camera>();
cam.orthographic = true;
cam.orthographicSize = 5f;
cam.clearFlags = CameraClearFlags.SolidColor;
cam.backgroundColor = new Color(0.05f, 0.05f, 0.1f, 1f);

// Top-down tilted 30 degrees: looking down at 60° from horizontal (30° from vertical)
// Rotation X=30 means tilted forward 30 degrees from looking straight down
camObj.transform.position = new Vector3(0f, 10f, -5.77f); // offset so the view centers on origin
camObj.transform.rotation = Quaternion.Euler(30f, 0f, 0f);

Debug.Log("Camera set up: orthographic, 30-degree tilt from top-down");

// === 2. Create ground plane with SpriteRenderer ===
var groundObj = new GameObject("Ground");
groundObj.transform.position = Vector3.zero;
var groundSr = groundObj.AddComponent<SpriteRenderer>();
groundSr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 4, 4), new Vector2(0.5f, 0.5f), 100f);
groundSr.color = new Color(0.35f, 0.35f, 0.4f, 1f);
groundSr.drawMode = SpriteDrawMode.Sliced;
groundSr.size = new Vector2(20f, 20f);
groundSr.sortingOrder = -10;

// Add a sorting group or ensure sorting layer
var groundSg = groundObj.AddComponent<SortingGroup>();
groundSg.sortingOrder = -10;

Debug.Log("Ground sprite created");

// === 3. Create some demo objects (sprites) to show lighting ===
// Create a few colored sprites at different positions
string[] objNames = { "RedBox", "GreenBox", "BlueBox" };
Color[] objColors = {
    new Color(0.9f, 0.2f, 0.2f, 1f),
    new Color(0.2f, 0.9f, 0.2f, 1f),
    new Color(0.2f, 0.2f, 0.9f, 1f)
};
Vector2[] objPositions = {
    new Vector2(-3f, -2f),
    new Vector2(0f, 1f),
    new Vector2(3f, -1f)
};

for (int i = 0; i < objNames.Length; i++)
{
    var obj = new GameObject(objNames[i]);
    obj.transform.position = new Vector3(objPositions[i].x, objPositions[i].y, 0f);
    var sr = obj.AddComponent<SpriteRenderer>();
    sr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 100f);
    sr.color = objColors[i];
    sr.sortingOrder = 0;

    var sg = obj.AddComponent<SortingGroup>();
    sg.sortingOrder = 0;
}

// White column/pillar
var pillarObj = new GameObject("WhitePillar");
pillarObj.transform.position = new Vector3(-1f, -3f, 0f);
var pillarSr = pillarObj.AddComponent<SpriteRenderer>();
pillarSr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 2), new Vector2(0.5f, 0.5f), 100f);
pillarSr.color = Color.white;
pillarSr.sortingOrder = 0;
var pillarSg = pillarObj.AddComponent<SortingGroup>();
pillarSg.sortingOrder = 0;

Debug.Log("Demo sprites created");

// === 4. Create 2D Lights ===

// 4a. Global 2D Light (ambient)
var globalLightObj = new GameObject("2D Global Light");
globalLightObj.transform.position = new Vector3(0f, 0f, 0f);
var globalLight2D = globalLightObj.AddComponent<Light2D>();
// Global light type
var globalLightTypeField = globalLight2D.GetType().GetField("m_LightType", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
if (globalLightTypeField != null)
    globalLightTypeField.SetValue(globalLight2D, (globalLight2D.lightType)); // will set via property
// Use the enum-based approach
globalLight2D.lightType = Light2D.LightType.Global;
globalLight2D.intensity = 0.3f;
globalLight2D.color = new Color(0.7f, 0.75f, 0.9f, 1f); // cool blue ambient

Debug.Log("2D Global Light created");

// 4b. Point Light - warm yellow (like a torch)
var pointLight1Obj = new GameObject("2D Point Light - Torch");
pointLight1Obj.transform.position = new Vector3(-3f, -2f, 0f);
var pointLight1 = pointLight1Obj.AddComponent<Light2D>();
pointLight1.lightType = Light2D.LightType.Point;
pointLight1.intensity = 1.2f;
pointLight1.color = new Color(1f, 0.85f, 0.4f, 1f); // warm yellow
pointLight1.pointLightOuterRadius = 5f;
pointLight1.pointLightInnerRadius = 0.5f;
pointLight1.falloffIntensity = 0.5f;

Debug.Log("2D Point Light (Torch) created");

// 4c. Point Light - green (magic glow)
var pointLight2Obj = new GameObject("2D Point Light - Magic");
pointLight2Obj.transform.position = new Vector3(0f, 1f, 0f);
var pointLight2 = pointLight2Obj.AddComponent<Light2D>();
pointLight2.lightType = Light2D.LightType.Point;
pointLight2.intensity = 1.0f;
pointLight2.color = new Color(0.3f, 1f, 0.5f, 1f); // green magic
pointLight2.pointLightOuterRadius = 4f;
pointLight2.pointLightInnerRadius = 0.3f;
pointLight2.falloffIntensity = 0.6f;

Debug.Log("2D Point Light (Magic) created");

// 4d. Point Light - blue (crystal)
var pointLight3Obj = new GameObject("2D Point Light - Crystal");
pointLight3Obj.transform.position = new Vector3(3f, -1f, 0f);
var pointLight3 = pointLight3Obj.AddComponent<Light2D>();
pointLight3.lightType = Light2D.LightType.Point;
pointLight3.intensity = 1.0f;
pointLight3.color = new Color(0.3f, 0.5f, 1f, 1f); // blue crystal
pointLight3.pointLightOuterRadius = 4f;
pointLight3.pointLightInnerRadius = 0.3f;
pointLight3.falloffIntensity = 0.5f;

Debug.Log("2D Point Light (Crystal) created");

// 4e. Freeform/Sprite Light for extra effect
var areaLightObj = new GameObject("2D Sprite Light - Ambient Area");
areaLightObj.transform.position = new Vector3(0f, -4f, 0f);
var areaLight = areaLightObj.AddComponent<Light2D>();
areaLight.lightType = Light2D.LightType.Freeform;
areaLight.intensity = 0.6f;
areaLight.color = new Color(1f, 0.6f, 0.2f, 1f); // warm orange ambient
areaLight.pointLightOuterRadius = 6f;
areaLight.pointLightInnerRadius = 1f;
areaLight.falloffIntensity = 0.8f;

Debug.Log("2D Sprite Light created");

// === 5. Add a Light2D renderer feature reminder (needs to be in URP asset) ===
Debug.Log("NOTE: Make sure the URP renderer asset has the '2D Renderer' or 'Light2D' renderer feature enabled.");

Debug.Log("=== 2D Lighting Demo scene setup complete! ===");

