using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

var urpAsset = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
if (urpAsset != null)
{
    Debug.Log("URP Asset: " + urpAsset.name);

    var type = urpAsset.GetType();

    // Check for m_RendererDataList field
    var field = type.GetField("m_RendererDataList", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (field != null)
    {
        var list = field.GetValue(urpAsset) as System.Collections.IList;
        if (list != null)
        {
            Debug.Log("Renderer data list count: " + list.Count);
            foreach (var item in list)
            {
                if (item != null)
                {
                    var srd = item as ScriptableRendererData;
                    Debug.Log("  Renderer: " + item.GetType().Name + " - " + (srd != null ? srd.name : "unnamed"));
                    if (item is Renderer2DData)
                        Debug.Log("    -> IS 2D Renderer!");
                }
                else
                {
                    Debug.Log("  Renderer: NULL");
                }
            }
        }
    }

    // Check what the actual camera sees
    var mainCam = Camera.main;
    if (mainCam != null)
    {
        var camData = mainCam.GetUniversalAdditionalCameraData();
        if (camData != null)
        {
            Debug.Log("Camera renderType: " + camData.renderType);
        }
    }

    // Get renderer type
    try
    {
        var renderer = urpAsset.GetRenderer(0);
        Debug.Log("Renderer 0 type: " + renderer.GetType().Name);
    }
    catch (System.Exception e)
    {
        Debug.Log("Error getting renderer: " + e.Message);
    }
}

// Check for 2D renderer assets in the project
var renderer2DAssets = AssetDatabase.FindAssets("t:Renderer2DData");
Debug.Log("2D Renderer assets found: " + renderer2DAssets.Length);
foreach (var guid in renderer2DAssets)
{
    var path = AssetDatabase.GUIDToAssetPath(guid);
    Debug.Log("  2D Renderer: " + path);
}

// Check for all renderer data assets
var allRendererAssets = AssetDatabase.FindAssets("t:ScriptableRendererData");
Debug.Log("All ScriptableRendererData assets found: " + allRendererAssets.Length);
foreach (var guid in allRendererAssets)
{
    var path = AssetDatabase.GUIDToAssetPath(guid);
    var obj = AssetDatabase.LoadAssetAtPath<ScriptableRendererData>(path);
    if (obj != null)
        Debug.Log("  Renderer: " + path + " type=" + obj.GetType().Name);
}

// Check URP asset path
var urpAssets = AssetDatabase.FindAssets("t:UniversalRenderPipelineAsset");
foreach (var guid in urpAssets)
{
    var path = AssetDatabase.GUIDToAssetPath(guid);
    Debug.Log("URP Asset path: " + path);
}

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

// Fix all SpriteRenderers to use Sprite-Lit-Default material for 2D lighting
var spriteRenderers = GameObject.FindObjectsOfType<SpriteRenderer>();
var litMat = new Material(Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default"));
Debug.Log("Created Sprite-Lit-Default material");

foreach (var sr in spriteRenderers)
{
    sr.sharedMaterial = litMat;
    Debug.Log("Set Sprite-Lit-Default on: " + sr.gameObject.name);
}

// Fix the camera position - bring it closer and adjust for better view
var camObj = Camera.main.gameObject;
// For orthographic top-down at 30 degree tilt, the camera should be positioned
// so that looking at 30 degrees pitch it sees the ground plane
// Position camera above and slightly behind, looking down at 30 degrees
camObj.transform.position = new Vector3(0f, 8f, -4.6f);
camObj.transform.rotation = Quaternion.Euler(30f, 0f, 0f);

var cam = camObj.GetComponent<Camera>();
cam.orthographicSize = 6f;

Debug.Log("Camera repositioned and sprites set to lit materials");

// Also verify lights are set up properly
var lights = GameObject.FindObjectsOfType<Light2D>();
foreach (var light in lights)
{
    Debug.Log("Light: " + light.gameObject.name + " type=" + light.lightType + " intensity=" + light.intensity + " color=" + light.color);
}

