using UnityEngine;
using UnityEngine.Rendering.Universal;

// Increase global light a bit for better visibility
var globalLight = GameObject.Find("2D Global Light");
if (globalLight != null)
{
    var l2d = globalLight.GetComponent<Light2D>();
    l2d.intensity = 0.4f;
    Debug.Log("Global light intensity set to 0.4");
}

// Add a few more interesting props to show lighting better
// Add a circle sprite (like a puddle) to show reflection
var puddle = new GameObject("Puddle");
puddle.transform.position = new Vector3(2f, 2f, 0f);
var puddleSr = puddle.AddComponent<SpriteRenderer>();
puddleSr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 100f);
puddleSr.color = new Color(0.5f, 0.6f, 0.8f, 1f); // light blue
puddleSr.transform.localScale = new Vector3(1.5f, 1f, 1f); // oval shape
puddleSr.sharedMaterial = new Material(Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default"));
puddleSr.sortingOrder = -5;
var puddleSg = puddle.AddComponent<SortingGroup>();
puddleSg.sortingOrder = -5;

// Add a wall/barrier sprite to show shadow casting
var wall = new GameObject("Wall");
wall.transform.position = new Vector3(5f, 0f, 0f);
var wallSr = wall.AddComponent<SpriteRenderer>();
wallSr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 4), new Vector2(0.5f, 0.5f), 100f);
wallSr.color = new Color(0.6f, 0.55f, 0.5f, 1f); // brownish
wallSr.sharedMaterial = new Material(Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default"));
var wallSg = wall.AddComponent<SortingGroup>();
wallSg.sortingOrder = 1;

// Add ShadowCaster2D to the wall for shadow demo
var shadowCaster = wall.AddComponent<ShadowCaster2D>();
shadowCaster.selfShadow = true;

Debug.Log("Added puddle, wall with shadow caster");

// Also add a slight warm point light near center for better visibility
var centerLightObj = new GameObject("2D Point Light - Center Warm");
centerLightObj.transform.position = new Vector3(0f, -1f, 0f);
var centerLight = centerLightObj.AddComponent<Light2D>();
centerLight.lightType = Light2D.LightType.Point;
centerLight.intensity = 0.5f;
centerLight.color = new Color(1f, 0.95f, 0.8f, 1f); // warm white
centerLight.pointLightOuterRadius = 8f;
centerLight.pointLightInnerRadius = 1f;
centerLight.falloffIntensity = 0.7f;

Debug.Log("Added center warm fill light");
Debug.Log("Scene enhancements complete!");

