using UnityEngine.Rendering.Universal;

// Add ShadowCaster2D to all sprites that don't have one
var sprites = GameObject.FindObjectsOfType<SpriteRenderer>();
int added = 0;
foreach (var sr in sprites)
{
    if (sr.gameObject.GetComponent<ShadowCaster2D>() == null)
    {
        sr.gameObject.AddComponent<ShadowCaster2D>();
        added++;
    }
}
Debug.Log("Added ShadowCaster2D to " + added + " objects");

// List all objects in scene
var allObj = GameObject.FindObjectsOfType<GameObject>();
foreach (var go in allObj)
{
    if (go.transform.parent == null)
        Debug.Log("Root: " + go.name + " pos=" + go.transform.position);
}

using UnityEngine;
using UnityEngine.Rendering.Universal;

// Reposition and tune lights to match the placed sprites

// Global light - brighter for lush vibrant feel
var global = GameObject.Find("2D Global Light").GetComponent<Light2D>();
global.intensity = 0.6f;
global.color = new Color(0.85f, 0.92f, 0.8f, 1f); // warm greenish daylight

// Torch light near cave entrance
var torch = GameObject.Find("2D Point Light - Torch").GetComponent<Light2D>();
torch.transform.position = new Vector3(-7f, 0f, 0f);
torch.intensity = 1.5f;
torch.pointLightOuterRadius = 6f;
torch.color = new Color(1f, 0.8f, 0.3f, 1f); // warm firelight

// Magic light near crystals
var magic = GameObject.Find("2D Point Light - Magic").GetComponent<Light2D>();
magic.transform.position = new Vector3(0f, 2.5f, 0f);
magic.intensity = 1.2f;
magic.pointLightOuterRadius = 4f;
magic.color = new Color(0.4f, 1f, 0.6f, 1f); // green magic

// Crystal light - blue near blue crystals
var crystal = GameObject.Find("2D Point Light - Crystal").GetComponent<Light2D>();
crystal.transform.position = new Vector3(0f, 2.5f, 0f);
crystal.intensity = 1.0f;
crystal.pointLightOuterRadius = 3.5f;
crystal.color = new Color(0.3f, 0.6f, 1f, 1f); // blue crystal glow

// Freeform light - warm under the stone arch
var freeform = GameObject.Find("2D Freeform Light - Warm Area").GetComponent<Light2D>();
freeform.transform.position = new Vector3(2f, -4f, 0f);
freeform.intensity = 0.8f;
freeform.pointLightOuterRadius = 5f;
freeform.color = new Color(1f, 0.7f, 0.3f, 1f);

// Center warm fill - repositioned
var center = GameObject.Find("2D Point Light - Center Warm").GetComponent<Light2D>();
center.transform.position = new Vector3(1f, 0f, 0f);
center.intensity = 0.7f;
center.pointLightOuterRadius = 10f;
center.pointLightInnerRadius = 2f;
center.color = new Color(1f, 0.95f, 0.85f, 1f);

// Add a new dappled sunlight effect near big tree
var sunObj = new GameObject("2D Point Light - Dappled Sun");
sunObj.transform.position = new Vector3(3f, 2f, 0f);
var sunLight = sunObj.AddComponent<Light2D>();
sunLight.lightType = Light2D.LightType.Point;
sunLight.intensity = 0.8f;
sunLight.color = new Color(1f, 0.97f, 0.85f, 1f); // warm sunlight
sunLight.pointLightOuterRadius = 5f;
sunLight.pointLightInnerRadius = 0.5f;
sunLight.falloffIntensity = 0.7f;
sunLight.shadowsEnabled = true;
sunLight.shadowIntensity = 0.8f;

// Add soft glow near magic device
var deviceLightObj = new GameObject("2D Point Light - Device Glow");
deviceLightObj.transform.position = new Vector3(6f, -3f, 0f);
var deviceLight = deviceLightObj.AddComponent<Light2D>();
deviceLight.lightType = Light2D.LightType.Point;
deviceLight.intensity = 0.6f;
deviceLight.color = new Color(0.6f, 0.8f, 1f, 1f); // cool tech blue
deviceLight.pointLightOuterRadius = 3f;
deviceLight.pointLightInnerRadius = 0.3f;
deviceLight.falloffIntensity = 0.6f;
deviceLight.shadowsEnabled = true;
deviceLight.shadowIntensity = 0.6f;

// Add warm glow near pedestal with blue sphere
var pedLightObj = new GameObject("2D Point Light - Pedestal Glow");
pedLightObj.transform.position = new Vector3(-2f, 4.5f, 0f);
var pedLight = pedLightObj.AddComponent<Light2D>();
pedLight.lightType = Light2D.LightType.Point;
pedLight.intensity = 0.7f;
pedLight.color = new Color(0.5f, 0.7f, 1f, 1f); // blue orb glow
pedLight.pointLightOuterRadius = 3f;
pedLight.pointLightInnerRadius = 0.2f;
pedLight.falloffIntensity = 0.5f;
pedLight.shadowsEnabled = true;
pedLight.shadowIntensity = 0.7f;

// Update camera to frame everything nicely
var cam = Camera.main;
cam.orthographicSize = 9f;

Debug.Log("Lights repositioned and tuned for lush green scene!");

