    Debug.Log("Sheet1 alpha is transparency: " + importer1.alphaIsTransparency);

    // Check SpriteImportData for mesh type via reflection
    var factory = importer1.GetType().GetProperty("spriteImportData", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (factory != null)
    {
        Debug.Log("Sheet1 has spriteImportData");
    }
}

var importer2 = AssetImporter.GetAtPath(path2) as TextureImporter;
if (importer2 != null)
{
    Debug.Log("Sheet2 sprite mode: " + importer2.spriteImportMode);
    Debug.Log("Sheet2 alpha source: " + importer2.alphaSource);
    Debug.Log("Sheet2 alpha is transparency: " + importer2.alphaIsTransparency);
}

// Check sprite physics shapes - these are what ShadowCaster2D uses with useRendererSilhouette
var sprites1 = AssetDatabase.LoadAllAssetRepresentationsAtPath(path1);
foreach (var s in sprites1)
{
    if (s is Sprite sp)
    {
        var physShapeCount = sp.GetPhysicsShapeCount();
        Debug.Log("Sheet1 Sprite " + sp.name + " physicsShapeCount=" + physShapeCount);
        if (physShapeCount > 0)
        {
            for (int i = 0; i < physShapeCount && i < 2; i++)
            {
                var points = new System.Collections.Generic.List<Vector2>();
                sp.GetPhysicsShape(i, points);
                Debug.Log("  Shape " + i + " points=" + points.Count);
            }
        }
        break;
    }
}

var sprites2 = AssetDatabase.LoadAllAssetRepresentationsAtPath(path2);
foreach (var s in sprites2)
{
    if (s is Sprite sp)
    {
        var physShapeCount = sp.GetPhysicsShapeCount();
        Debug.Log("Sheet2 Sprite " + sp.name + " physicsShapeCount=" + physShapeCount);
        break;
    }
}

