using UnityEngine;
using UnityEngine.Rendering.Universal;

// The Ground sprite was created from Texture2D.whiteTexture - it has no proper outline
// Remove ShadowCaster2D from Ground since it shouldn't cast shadows (it's the receiver)
var ground = GameObject.Find("Ground");
var groundSc = ground.GetComponent<ShadowCaster2D>();
if (groundSc != null)
{
    Object.DestroyImmediate(groundSc);
    Debug.Log("Removed ShadowCaster2D from Ground (it's the shadow receiver)");
}

// Check current state of ShadowCaster2D on a few sprites
var casters = GameObject.FindObjectsOfType<ShadowCaster2D>();
foreach (var sc in casters)
{
    var sr = sc.GetComponent<SpriteRenderer>();
    if (sr != null && sr.sprite != null)
    {
        var physCount = sr.sprite.GetPhysicsShapeCount();
        Debug.Log(sc.gameObject.name + ": useRendererSilhouette=" + sc.useRendererSilhouette + " spritePhysicsShapes=" + physCount);
    }
}

// Also check what the ShadowCaster2D shape path looks like via reflection
foreach (var sc in casters)
{
    var shapeField = sc.GetType().GetField("m_ShapePath", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (shapeField != null)
    {
        var path = shapeField.GetValue(sc) as System.Collections.Generic.List<Vector2>;
        if (path != null)
            Debug.Log(sc.gameObject.name + " m_ShapePath points: " + path.Count);
        else
            Debug.Log(sc.gameObject.name + " m_ShapePath: null");
    }
}

using UnityEngine;
using UnityEditor;

// Check the sprite import settings for outline detail
var path1 = "Assets/Flynn/Sprites/Environment/island_edges_caves_lighting_sheet_v1_transparent.png";

var importer1 = AssetImporter.GetAtPath(path1) as TextureImporter;
if (importer1 != null)
{
    // Get the sprite sheet texture provider to check per-sprite settings
    var provider = new SpriteSheetDataProvider(importer1);

    // Check via serialized object for outline settings
    var so = new SerializedObject(importer1);
    var outlineTolerance = so.FindProperty("m_SpriteSheet.m_Sprites");
    if (outlineTolerance != null && outlineTolerance.arraySize > 0)
    {
        var first = outlineTolerance.GetArrayElementAtIndex(0);
        var prop = first.Copy();
        var children = prop.GetEnumerator();
        while (children.MoveNext())
        {
            var child = children.Current as SerializedProperty;
            if (child != null)
            {
                Debug.Log("  Sprite[0] prop: " + child.name + " = " + child.stringValue);
            }
        }
    }

    // Simpler approach: check the sprite outline via the sprite itself
    var sprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(path1);
    foreach (var s in sprites)
    {
        if (s is Sprite sp)
        {
            // Check the sprite's vertices (render mesh)
            var verts = sp.vertices;
            Debug.Log("Sprite: " + sp.name + " vertexCount=" + verts.Length + " bounds=" + sp.bounds);

            // Check physics shape detail
            for (int i = 0; i < sp.GetPhysicsShapeCount(); i++)
            {
                var pts = new System.Collections.Generic.List<Vector2>();
                sp.GetPhysicsShape(i, pts);
                Debug.Log("  PhysicsShape[" + i + "]: " + pts.Count + " points, first3: " + 
                    (pts.Count > 0 ? pts[0].ToString() : "") + " " + 
                    (pts.Count > 1 ? pts[1].ToString() : "") + " " + 
                    (pts.Count > 2 ? pts[2].ToString() : ""));
            }
            break; // just first
        }
    }
}

