using UnityEngine;
using UnityEngine.Rendering.Universal;

// Set ShadowCaster2D shape paths from the sprite's physics shapes (which follow alpha)
// This overrides useRendererSilhouette with explicit high-detail paths
var casters = GameObject.FindObjectsOfType<ShadowCaster2D>();
int updated = 0;

foreach (var sc in casters)
{
    var sr = sc.GetComponent<SpriteRenderer>();
    if (sr == null || sr.sprite == null) continue;

    var sprite = sr.sprite;
    var physShapeCount = sprite.GetPhysicsShapeCount();
    if (physShapeCount == 0) continue;

    // Get the first physics shape (main outline)
    var shapePoints = new System.Collections.Generic.List<Vector2>();
    sprite.GetPhysicsShape(0, shapePoints);

    if (shapePoints.Count < 3) continue;

    // Convert from sprite-local space to the shape path format
    // Sprite physics shapes are in sprite space (pixels from bottom-left of rect)
    // Need to convert to normalized coords relative to sprite bounds
    var bounds = sprite.bounds;
    var rect = sprite.rect;

    var shapePath = new System.Collections.Generic.List<Vector2>();
    foreach (var pt in shapePoints)
    {
        // Physics shape points are in sprite pixel coordinates
        // Convert to local space relative to pivot
        float x = (pt.x - rect.width * sprite.pivot.x / rect.width) / sprite.pixelsPerUnit;
        float y = (pt.y - rect.height * sprite.pivot.y / rect.height) / sprite.pixelsPerUnit;

        // Apply the transform's scale
        var scale = sc.transform.lossyScale;
        if (scale.x != 0) x /= scale.x;
        if (scale.y != 0) y /= scale.y;

        shapePath.Add(new Vector2(x, y));
    }

    // Set via reflection
    var shapeField = sc.GetType().GetField("m_ShapePath", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (shapeField != null)
    {
        shapeField.SetValue(sc, shapePath);
        sc.useRendererSilhouette = false;
        updated++;
        Debug.Log("Set shape path on " + sc.gameObject.name + ": " + shapePath.Count + " points");
    }
}

