using UnityEngine;
using UnityEngine.Rendering.Universal;

// Process shadow casters in batches to avoid timeout
// Reduce point count by sampling every Nth point
var casters = GameObject.FindObjectsOfType<ShadowCaster2D>();
int updated = 0;

foreach (var sc in casters)
{
    var sr = sc.GetComponent<SpriteRenderer>();
    if (sr == null || sr.sprite == null) continue;

    var sprite = sr.sprite;
    if (sprite.GetPhysicsShapeCount() == 0) continue;

    var pts = new System.Collections.Generic.List<Vector2>();
    sprite.GetPhysicsShape(0, pts);
    if (pts.Count < 3) continue;

    // Simplify: take every Nth point, keep at most 24 points
    int step = Mathf.Max(1, pts.Count / 24);
    var shapePath = new System.Collections.Generic.List<Vector2>();
    for (int i = 0; i < pts.Count; i += step)
    {
        shapePath.Add(pts[i]);
    }
    // Ensure we close the shape by adding the first point if needed
    if (shapePath.Count > 0 && shapePath[0] != shapePath[shapePath.Count - 1])
        shapePath.Add(shapePath[0]);

    var shapeField = sc.GetType().GetField("m_ShapePath", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (shapeField != null)
    {
        shapeField.SetValue(sc, shapePath);
        sc.useRendererSilhouette = false;
        updated++;
    }
}

