using UnityEngine;
using UnityEngine.Rendering.Universal;
using UnityEditor;

public class FixShadowShapes
{
    static int lastIndex = 0;

    [MenuItem("Flynn/Fix Shadow Casters - Batch")]
    public static void FixBatch()
    {
        var casters = Object.FindObjectsOfType<ShadowCaster2D>();
        int updated = 0;
        int batchSize = 6;

        for (int i = lastIndex; i < Mathf.Min(casters.Length, lastIndex + batchSize); i++)
        {
            var sc = casters[i];
            var sr = sc.GetComponent<SpriteRenderer>();
            if (sr == null || sr.sprite == null) continue;

            var sprite = sr.sprite;
            if (sprite.GetPhysicsShapeCount() == 0) continue;

            var pts = new System.Collections.Generic.List<Vector2>();
            sprite.GetPhysicsShape(0, pts);
            if (pts.Count < 3) continue;

            // Simplify to max 20 points
            int step = Mathf.Max(1, pts.Count / 20);
            var shapePath = new System.Collections.Generic.List<Vector2>();
            for (int j = 0; j < pts.Count; j += step)
                shapePath.Add(pts[j]);

            // Close the shape
            if (shapePath.Count > 2 && shapePath[0] != shapePath[shapePath.Count - 1])
                shapePath.Add(shapePath[0]);

            var shapeField = sc.GetType().GetField("m_ShapePath",
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (shapeField != null)
            {
                shapeField.SetValue(sc, shapePath);
                sc.useRendererSilhouette = false;
                updated++;
                Debug.Log("Fixed: " + sc.gameObject.name + " (" + shapePath.Count + " pts)");
            }
        }

        lastIndex += batchSize;
        if (lastIndex >= casters.Length)
        {
            Debug.Log("ALL DONE - Fixed all shadow casters");
            lastIndex = 0;
        }
        else
        {
            Debug.Log("Batch done. Progress: " + lastIndex + "/" + casters.Length + " - Run again for next batch");
        }
    }

    [MenuItem("Flynn/Fix Shadow Casters - Reset")]
    public static void Reset()
    {
        lastIndex = 0;
        Debug.Log("Reset batch counter");
    }
}

