    if (sr != null)
    {
        Debug.Log("  SpriteRenderer pos=" + sr.transform.position + " sprite=" + (sr.sprite != null ? sr.sprite.name : "null"));
    }
}

// The ShadowManager projects shadows onto XZ ground plane
// but in a 2D scene objects are on XY plane and camera looks along Z
// The shadow quads are facing up (Y axis) but camera looks along Z
// So shadows are invisible - they're perpendicular to the camera

Debug.Log("ShadowManager is 2.5D (XZ ground). This 2D scene needs XY shadows.");
Debug.Log("Need a different approach for pure 2D scenes.");

using UnityEngine;

// Remove ShadowManager (it's for 2.5D, not our 2D scene)
var sm = FindObjectOfType<ShadowManager>();
if (sm != null) Object.DestroyImmediate(sm.gameObject);
Debug.Log("Removed ShadowManager");

// Remove ShadowTarget from all objects (no longer needed)
var targets = FindObjectsOfType<ShadowTarget>();
foreach (var t in targets) Object.DestroyImmediate(t);
Debug.Log("Removed " + targets.Length + " ShadowTarget components");

// Now add simple dark oval shadows under each sprite
var sprites = FindObjectsOfType<SpriteRenderer>();
int shadowsCreated = 0;
var shadowMat = new Material(Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default"));

foreach (var sr in sprites)
{
    if (sr.gameObject.name == "Ground") continue;

    // Create shadow oval as child
    var shadowObj = new GameObject("_shadow");
    shadowObj.transform.SetParent(sr.transform, false);

    // Position below the sprite (offset Y downward)
    var spriteBounds = sr.sprite != null ? sr.sprite.bounds : new Bounds(Vector3.zero, Vector3.one);
    float offsetY = -spriteBounds.extents.y * 0.8f;
    shadowObj.transform.localPosition = new Vector3(0f, offsetY, 0.01f);

    var shadowSr = shadowObj.AddComponent<SpriteRenderer>();
    shadowSr.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 4, 4), new Vector2(0.5f, 0.5f), 100f);
    shadowSr.color = new Color(0f, 0f, 0f, 0.35f); // dark semi-transparent
    shadowSr.sharedMaterial = shadowMat;
    shadowSr.sortingOrder = -1; // behind the parent sprite

    // Make it an oval - wider than tall
    float width = spriteBounds.size.x * 0.9f;
    float height = spriteBounds.size.y * 0.3f;
    shadowObj.transform.localScale = new Vector3(width, height, 1f);

    shadowsCreated++;
}
Debug.Log("Created " + shadowsCreated + " dark oval shadows");

