using UnityEngine;
using UnityEditor;

// Load the shadow oval sprite from the sprite sheet
var shadowSprite = AssetDatabase.LoadAssetAtPath<Sprite>(
    "Assets/Flynn/Sprites/Environment/island_edges_caves_lighting_sheet_v1_transparent.png"
);
// Need to load the specific sub-asset _24
var allSprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(
    "Assets/Flynn/Sprites/Environment/island_edges_caves_lighting_sheet_v1_transparent.png"
);

Sprite ovalSprite = null;
foreach (var s in allSprites)
{
    if (s is Sprite sp && sp.name.EndsWith("_24"))
    {
        ovalSprite = sp;
        break;
    }
}

if (ovalSprite == null)
{
    Debug.LogError("Shadow oval sprite _24 not found!");
}
else
{
    Debug.Log("Found shadow oval: " + ovalSprite.name + " rect=" + ovalSprite.rect);
}

// Update all _shadow children
var allSr = GameObject.FindObjectsOfType<SpriteRenderer>();
int updated = 0;
foreach (var sr in allSr)
{
    if (sr.gameObject.name == "_shadow" && ovalSprite != null)
    {
        sr.sprite = ovalSprite;
        sr.color = new Color(0f, 0f, 0f, 0.4f);

        // Rescale to match parent sprite size
        var parent = sr.transform.parent;
        if (parent != null)
        {
            var parentSr = parent.GetComponent<SpriteRenderer>();
            if (parentSr != null && parentSr.sprite != null)
            {
                var parentBounds = parentSr.sprite.bounds;
                float widthScale = parentBounds.size.x * 1.1f;
                float heightScale = parentBounds.size.y * 0.4f;
                sr.transform.localScale = new Vector3(widthScale, heightScale, 1f);

                // Reposition to bottom of parent sprite
                float offsetY = -parentBounds.extents.y * 0.7f;
                sr.transform.localPosition = new Vector3(0f, offsetY, 0.01f);
            }
        }
        updated++;
    }
}
Debug.Log("Updated " + updated + " shadow ovals");

