    "Assets/Flynn/Sprites/Environment/island_edges_caves_lighting_sheet_v1_transparent.png");
var sheet2Sprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(
    "Assets/Flynn/Sprites/Environment/key_environment_sprite_sheet_v1_transparent.png");

var s1 = new System.Collections.Generic.Dictionary<int, Sprite>();
var s2 = new System.Collections.Generic.Dictionary<int, Sprite>();

foreach (var s in sheet1Sprites)
    if (s is Sprite sp)
    { var n = sp.name.Substring(sp.name.LastIndexOf('_') + 1); if (int.TryParse(n, out int i)) s1[i] = sp; }
foreach (var s in sheet2Sprites)
    if (s is Sprite sp)
    { var n = sp.name.Substring(sp.name.LastIndexOf('_') + 1); if (int.TryParse(n, out int i)) s2[i] = sp; }

Debug.Log("Sheet1: " + s1.Count + " sprites, Sheet2: " + s2.Count + " sprites");

// Assign correct sprites: name -> (sheet, index)
void Assign(string objName, int sheet, int idx)
{
    var go = GameObject.Find(objName);
    if (go == null) return;
    var sr = go.GetComponent<SpriteRenderer>();
    if (sr == null) return;
    var dict = sheet == 1 ? s1 : s2;
    if (dict.TryGetValue(idx, out var sprite)) { sr.sprite = sprite; Debug.Log(objName + " -> " + sprite.name); }
    else Debug.LogWarning(objName + ": sprite idx " + idx + " not in sheet " + sheet);
}

// key_environment sheet (2): 0=sapling, 1=young_tree, 2=big_tree, 3=bush, 4=large_bush,
//   6=branches, 7=log_pile, 8=rubble, 10=arch, 11=stairs, 12=pedestal, 13=crystals, 14=crate, 15=device
Assign("BigTree", 2, 2);
Assign("Sapling1", 2, 0);
Assign("YoungTree1", 2, 1);
Assign("YoungTree2", 2, 1);
Assign("Bush1", 2, 3);
Assign("Bush2", 2, 3);
Assign("Bush3", 2, 3);
Assign("LargeBush", 2, 4);
Assign("LogPile", 2, 7);
Assign("BranchPile", 2, 6);
Assign("StoneStairs", 2, 11);
Assign("StoneArch", 2, 10);
Assign("BlueCrystals", 2, 13);
Assign("Crate", 2, 14);
Assign("MagicDevice", 2, 15);
Assign("Pedestal", 2, 12);
Assign("Rubble", 2, 8);

// island_edges sheet (1): 0=grass_strip, 2=small_block, 3=raised_terrain,
//   4=cave, 6=hanging_roots, 7=stone_ruins, 9=paving, 10=glowing_puddle
Assign("CaveEntrance", 1, 4);
Assign("RaisedTerrain", 1, 3);
Assign("GrassEdge", 1, 0);
Assign("HangingRoots", 1, 6);
Assign("StoneRuins", 1, 7);
Assign("SmallTerrain", 1, 2);
Assign("GlowingPuddle", 1, 10);
Assign("PavingStones", 1, 9);

Debug.Log("=== Sprite assignments complete ===");

using UnityEngine;

// Fix GlowingPuddle - use island_edges sprite 5 (well/circular structure) instead
var go = GameObject.Find("GlowingPuddle");
if (go != null)
{
    var sr = go.GetComponent<SpriteRenderer>();
    // Sprite 11 is the dark puddle/teal splatter from the earlier analysis
    var sprites = UnityEditor.AssetDatabase.LoadAllAssetRepresentationsAtPath(
        "Assets/Flynn/Sprites/Environment/island_edges_caves_lighting_sheet_v1_transparent.png");
