using UnityEngine;
using UnityEngine.Rendering.Universal;

// 1. Remove all existing _shadow oval children
var allSr = GameObject.FindObjectsOfType<SpriteRenderer>();
int removed = 0;
foreach (var sr in allSr)
{
    if (sr.gameObject.name == "_shadow")
    {
        Object.DestroyImmediate(sr.gameObject);
        removed++;
    }
}
Debug.Log("Removed " + removed + " old _shadow ovals");

// 2. Create Shadow2DManager
var smObj = new GameObject("Shadow2DManager");
var sm = smObj.AddComponent<Shadow2DManager>();
Debug.Log("Created Shadow2DManager");

// 3. Set the light source to the existing Global Light2D
var globalLight = GameObject.Find("2D Global Light");
if (globalLight != null)
{
    var light2d = globalLight.GetComponent<Light2D>();
    // Set via serialized field
    var so = new UnityEditor.SerializedObject(sm);
    so.FindProperty("_lightSource").objectReferenceValue = light2d;
    so.FindProperty("_manualLightDir").vector2Value = new Vector2(-0.5f, -1f);
    so.FindProperty("_stretchScale").floatValue = 1.2f;
    so.FindProperty("_minStretch").floatValue = 0.3f;
    so.FindProperty("_maxStretch").floatValue = 3f;
    so.FindProperty("_baseOffset").floatValue = 0.1f;
    so.ApplyModifiedProperties();
    Debug.Log("Configured Shadow2DManager with Global Light reference");
}

// 4. Add Shadow2DTarget to all sprites (except Ground)
var sprites = GameObject.FindObjectsOfType<SpriteRenderer>();
int added = 0;
foreach (var sr in sprites)
{
    if (sr.gameObject.name == "Ground" || sr.gameObject.name.StartsWith("_shadow")) continue;
    if (sr.gameObject.GetComponent<Shadow2DTarget>() == null && sr.gameObject.GetComponent<Shadow2DManager>() == null)
    {
        sr.gameObject.AddComponent<Shadow2DTarget>();
        added++;
    }
}
Debug.Log("Added Shadow2DTarget to " + added + " objects");

