using UnityEngine;
using UnityEngine.Rendering.Universal;

var sm = FindObjectOfType<Shadow2DManager>();
if (sm == null) { Debug.LogError("No Shadow2DManager!"); return; }

// Check targets registered
var so = new UnityEditor.SerializedObject(sm);
var lightRef = so.FindProperty("_lightSource");
var manualDir = so.FindProperty("_manualLightDir");
Debug.Log("Light source: " + (lightRef.objectReferenceValue != null ? lightRef.objectReferenceValue.name : "null"));
Debug.Log("Manual dir: " + manualDir.vector2Value);

// Force a re-register of all targets
var targets = FindObjectsOfType<Shadow2DTarget>();
foreach (var t in targets)
{
    sm.Unregister(t);
    sm.Register(t);
}
Debug.Log("Re-registered " + targets.Length + " Shadow2DTargets");

// Check if any shadow objects were created
foreach (var child in sm.transform)
{
    var c = ((Transform)child).gameObject;
    var sr = c.GetComponentInChildren<SpriteRenderer>();
    if (sr != null)
    {
        Debug.Log("Shadow obj: " + c.name + " active=" + c.activeSelf + " sprite=" + (sr.sprite != null ? sr.sprite.name : "null") + " pos=" + c.transform.position);
    }
}

using UnityEngine;
using UnityEngine.Rendering.Universal;

var sm = FindObjectOfType<Shadow2DManager>();
var globalLight = GameObject.Find("2D Global Light");

// Set the light source properly via the serialized object and mark dirty
var so = new UnityEditor.SerializedObject(sm);
so.FindProperty("_lightSource").objectReferenceValue = globalLight.GetComponent<Light2D>();
so.FindProperty("_manualLightDir").vector2Value = new Vector2(-0.5f, -1f);
so.FindProperty("_stretchScale").floatValue = 1.5f;
so.FindProperty("_minStretch").floatValue = 0.4f;
so.FindProperty("_maxStretch").floatValue = 4f;
so.FindProperty("_baseOffset").floatValue = 0.2f;
so.ApplyModifiedProperties();
UnityEditor.EditorUtility.SetDirty(sm);
Debug.Log("Set light source: " + globalLight.name);

// Check one shadow object's material
foreach (var child in sm.transform)
{
    var sr = ((Transform)child).GetComponentInChildren<SpriteRenderer>();
    if (sr != null)
    {
        Debug.Log("Shadow material: " + (sr.sharedMaterial != null ? sr.sharedMaterial.name : "null"));
        Debug.Log("Shadow color: " + sr.color);
        var mpb = new MaterialPropertyBlock();
        sr.GetPropertyBlock(mpb);
        Debug.Log("ShadowDirX: " + mpb.GetFloat(Shader.PropertyToID("_ShadowDirX")));
        Debug.Log("ShadowDirY: " + mpb.GetFloat(Shader.PropertyToID("_ShadowDirY")));
        Debug.Log("ShadowStretch: " + mpb.GetFloat(Shader.PropertyToID("_ShadowStretch")));
        Debug.Log("Opacity: " + mpb.GetFloat(Shader.PropertyToID("_Opacity")));
        break;
    }
}

