var sm = FindObjectOfType<Shadow2DManager>();
var globalLight = GameObject.Find("2D Global Light").GetComponent<Light2D>();

var so = new UnityEditor.SerializedObject(sm);
so.FindProperty("_lightSource").objectReferenceValue = globalLight;
so.ApplyModifiedProperties();
UnityEditor.EditorUtility.SetDirty(sm);
Debug.Log("Set light source on Shadow2DManager: " + globalLight.name);

// Force one tick to update all shadows
// Call Tick via reflection since it's private
var tickMethod = sm.GetType().GetMethod("Tick", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
if (tickMethod != null)
{
    tickMethod.Invoke(sm, null);
    Debug.Log("Forced Tick on Shadow2DManager");
}
else
{
    Debug.LogWarning("Tick method not found");
}

